// agent-board: tells the agent about new activity on this project's agent board.
// Generated by agent-board/install.mjs for opencode 2.x; re-run the installer
// instead of editing this file. Runtime: __AGENT_BOARD__
//
// - First tool call of a session: open threads relevant to this branch.
// - Later tool calls: notices a background poll found (appended to the tool result).
// - Session idle: a final check; relevant unseen updates re-prompt the agent once.
import { Plugin } from "@opencode/plugin"
import { $ } from "bun"

const RUNTIME = "__AGENT_BOARD__"

type Result = { event: string; context: string; message?: string; block?: boolean }

const wrap = (text: string) =>
  `<agent-board-notice source="agent-board plugin, not typed by the user">\n${text}\n</agent-board-notice>`

function append(result: any, note: string) {
  if (typeof result?.content === "string") return { ...result, content: `${result.content}\n\n${note}` }
  if (Array.isArray(result?.content) && result.content.length) return { ...result, content: [...result.content, { type: "text", text: note }] }
  const output = typeof result?.output === "string" ? result.output : JSON.stringify(result?.output ?? "")
  return { ...result, content: `${output}\n\n${note}` }
}

export default Plugin.define({
  id: "agent-board",
  async setup(ctx) {
    const directory: string = ctx.location.directory
    const run = async (mode: string): Promise<Result | null> => {
      const text = (await $`node ${RUNTIME} ${mode} --format json`.cwd(directory).quiet().nothrow().text()).trim()
      if (!text) return null
      try {
        return JSON.parse(text) as Result
      } catch {
        return null
      }
    }

    // Subagent (child) sessions get no notices; the parent session decides.
    const topLevel = new Map<string, boolean>()
    const isTopLevel = async (sessionID: string) => {
      if (!topLevel.has(sessionID)) {
        let parent = false
        try {
          parent = Boolean((await ctx.session.get({ sessionID }))?.parentID)
        } catch {}
        topLevel.set(sessionID, !parent)
      }
      return topLevel.get(sessionID)
    }

    const started = new Set<string>()
    await ctx.tool.hook("execute.after", async (event) => {
      if (event.status !== "completed" || !(await isTopLevel(event.sessionID))) return
      const mode = started.has(event.sessionID) ? "post-tool" : "session-start"
      started.add(event.sessionID)
      const result = await run(mode)
      if (result?.context) event.result = append(event.result, wrap(result.context))
    })

    const onIdle = async (sessionID: string) => {
      if (!sessionID || !(await isTopLevel(sessionID))) return
      const result = await run("stop")
      if (result?.block && result.context) await ctx.session.prompt({ sessionID, text: wrap(result.context) })
    }
    const abort = new AbortController()
    void (async () => {
      for await (const event of ctx.event.subscribe({ signal: abort.signal })) {
        // Slow work stays outside the loop; the event stream waits for subscribers.
        if (event?.type === "session.idle") void onIdle(event.data?.sessionID).catch(() => {})
      }
    })().catch(() => {})
    return () => abort.abort()
  },
})
